window.SITE_TEMPLATES={home:`<section class="hero container">
      <div class="hero-copy"><span class="eyebrow"><span class="eyebrow-dot"></span> Transformando realidades desde 2014</span><h1>Pequenos gestos.<br><em>Grandes futuros.</em></h1><p>Acreditamos que toda crian\xE7a merece crescer com oportunidades. Juntos, criamos caminhos para um amanh\xE3 mais justo e cheio de possibilidades.</p><div class="hero-actions"><a class="button button-primary" href="#/cadastro" data-route="cadastro">Fa\xE7a parte dessa mudan\xE7a <span aria-hidden="true">\u2192</span></a><a class="text-link" href="#/projetos" data-route="projetos">Conhe\xE7a nosso trabalho <span aria-hidden="true">\u2197</span></a></div><div class="hero-proof"><div class="avatar-stack" aria-hidden="true"><span>LM</span><span>CA</span><span>JP</span><span>+</span></div><p><strong>Mais de 1.200 pessoas</strong><br>j\xE1 caminham com a gente</p></div></div>
      <div class="hero-visual"><div class="image-frame"><picture><img src="imagens/foto1.jpg" alt="Crian\xE7as participam de uma atividade educativa em grupo"></picture><div class="image-caption"><span class="caption-icon" aria-hidden="true">\u2733</span><span><strong>Presen\xE7a que transforma</strong><small>Em 8 comunidades da regi\xE3o</small></span></div></div><div class="floating-note"><span class="note-icon" aria-hidden="true">\u2665</span><span><strong>2.480</strong><small>vidas alcan\xE7adas</small></span></div><div class="sunburst" aria-hidden="true">\u2733</div></div>
    </section>
    <section class="impact-band" aria-label="Nosso impacto em n\xFAmeros"><div class="container impact-grid"><div class="impact-intro"><span class="eyebrow eyebrow-light">O impacto \xE9 coletivo</span><h2>Juntos, j\xE1 fizemos<br>muita coisa acontecer.</h2></div><div class="impact-stat"><strong>2.4<span>k</span></strong><span>pessoas alcan\xE7adas</span></div><div class="impact-stat"><strong>08</strong><span>comunidades atendidas</span></div><div class="impact-stat"><strong>340</strong><span>volunt\xE1rios ativos</span></div></div></section>
    <section class="home-about section-space container" aria-labelledby="sobre-titulo"><div class="about-art"><picture><img src="imagens/foto1.jpg" alt="Crian\xE7as participam de uma atividade educativa em grupo"></picture><span class="art-caption">Nossa comunidade em a\xE7\xE3o</span></div><div class="about-copy"><span class="eyebrow">Quem somos</span><h2 id="sobre-titulo">O futuro floresce<br>quando <em>cuidamos juntos.</em></h2><p>Somos uma organiza\xE7\xE3o sem fins lucrativos que conecta pessoas, conhecimento e recursos para fortalecer crian\xE7as, jovens e fam\xEDlias em situa\xE7\xE3o de vulnerabilidade.</p><p>Trabalhamos lado a lado com cada comunidade, valorizando suas pot\xEAncias e construindo solu\xE7\xF5es que duram.</p><a class="text-link" href="#/projetos" data-route="projetos">Veja como fazemos isso <span aria-hidden="true">\u2192</span></a></div></section>
    <section class="contact-section" aria-labelledby="contato-titulo"><div class="container contact-inner"><div><span class="eyebrow">Fale com a gente</span><h2 id="contato-titulo">Vamos conversar?</h2><p>Entre em contato para conhecer melhor nosso trabalho ou tirar d\xFAvidas sobre como participar.</p></div><address><p><strong>E-mail</strong><br><a href="mailto:contato@raizesdoamanha.org.br">contato@raizesdoamanha.org.br</a></p><p><strong>Telefone</strong><br><a href="tel:+551130001234">(11) 3000-1234</a></p><p><strong>Endere\xE7o</strong><br>Rua das Flores, 120 \u2014 S\xE3o Paulo, SP</p></address></div></section>
    <section class="callout container"><div><span class="eyebrow eyebrow-light">Toda ajuda conta</span><h2>Tem um lugar pra voc\xEA<br>nessa hist\xF3ria.</h2><p>Doe seu tempo, talento ou recurso. O pr\xF3ximo passo pode come\xE7ar hoje.</p></div><a class="button button-light" href="#/cadastro" data-route="cadastro">Quero participar <span aria-hidden="true">\u2192</span></a><span class="callout-flower" aria-hidden="true">\u2733</span></section>`,projetos:`<section class="page-hero container"><div><span class="eyebrow"><span class="eyebrow-dot"></span> A mudan\xE7a acontece em conjunto</span><h1>Oportunidades que<br><em>criam ra\xEDzes.</em></h1><p>Nossos projetos nascem da escuta e crescem com a for\xE7a de cada comunidade. Conhe\xE7a as frentes que fazem o futuro florescer.</p></div><div class="page-hero-art"><span class="page-art-symbol" aria-hidden="true">\u2733</span><span class="page-art-caption">Cuidado que cria caminhos</span></div></section>
    <section class="projects-section"><div class="container"><div class="section-heading"><div><span class="eyebrow">Nossas frentes de atua\xE7\xE3o</span><h2>Um ciclo de cuidado,<br><em>aprendizado e futuro.</em></h2></div><p>Atuamos de forma integrada para que cada pessoa tenha acesso \xE0s ferramentas necess\xE1rias para construir seus pr\xF3prios caminhos.</p></div>
      <div class="project-grid"><article class="project-card project-card-feature"><div class="project-image project-image-one"><picture><img src="imagens/foto2.jpg" alt="Crian\xE7as participam de uma atividade educativa"></picture><span class="project-number">01 / EDUCA\xC7\xC3O</span></div><div class="project-body"><span class="badge badge-success">Em andamento</span><span class="card-kicker">Aprender para florescer</span><h3>Quintal do Saber</h3><p>Refor\xE7o escolar, leitura e oficinas criativas em um espa\xE7o seguro onde a curiosidade \xE9 sempre bem-vinda.</p><div class="project-meta"><span><strong>180</strong> crian\xE7as por ano</span><span class="meta-separator">\xB7</span><span>Zona Norte</span></div></div></article>
      <article class="project-card"><div class="project-image project-image-two"><picture><img src="imagens/foto3.jpg" alt="Fam\xEDlia reunida em um momento de conviv\xEAncia"></picture><span class="project-number">02 / BEM-ESTAR</span></div><div class="project-body"><span class="badge badge-info">Inscri\xE7\xF5es abertas</span><span class="card-kicker">Cuidar de quem cuida</span><h3>Rede de Afeto</h3><p>Acolhimento, rodas de conversa e orienta\xE7\xE3o para fam\xEDlias fortalecerem seus v\xEDnculos e redes de apoio.</p><div class="project-meta"><span><strong>95</strong> fam\xEDlias acompanhadas</span><span class="meta-separator">\xB7</span><span>4 bairros</span></div></div></article>
      <article class="project-card"><div class="project-image project-image-three"><picture><img src="imagens/foto4.jpg" alt="Jovens reunidos em uma atividade em grupo"></picture><span class="project-number">03 / JUVENTUDE</span></div><div class="project-body"><span class="badge badge-neutral">Conclu\xEDdo</span><span class="card-kicker">Novos caminhos</span><h3>Primeiro Passo</h3><p>Mentoria, forma\xE7\xE3o e conex\xE3o com oportunidades de trabalho para jovens descobrirem seu potencial.</p><div class="project-meta"><span><strong>72</strong> jovens formados</span><span class="meta-separator">\xB7</span><span>Desde 2022</span></div></div></article></div>
    </div></section>
    <section class="feedback-section container" aria-labelledby="feedback-titulo"><div class="section-heading"><div><span class="eyebrow">Fa\xE7a parte dos nossos projetos</span><h2 id="feedback-titulo">Toda ajuda faz diferen\xE7a</h2></div><p>H\xE1 muitas formas de apoiar as crian\xE7as, jovens e fam\xEDlias atendidas pela Ra\xEDzes do Amanh\xE3.</p></div>
      <div class="alert alert-success" role="note"><span class="alert-icon" aria-hidden="true">\u2713</span><div><strong>Inscri\xE7\xF5es abertas</strong><p>Voc\xEA j\xE1 pode se cadastrar para participar das pr\xF3ximas atividades do Quintal do Saber.</p></div></div>
      <div class="alert alert-warning" role="note"><span class="alert-icon" aria-hidden="true">!</span><div><strong>Vagas limitadas</strong><p>Preencha o cadastro para conversar com nossa equipe e encontrar a melhor forma de colaborar.</p></div></div>
      <div class="feedback-actions"><button class="button button-primary" type="button" data-open-modal>Quero participar</button><button class="button button-outline" type="button" data-show-toast>Falar com a equipe</button></div>
    </section>
    <div class="toast" id="feedback-toast" role="status" aria-live="polite" aria-atomic="true" hidden><span class="alert-icon" aria-hidden="true">\u2709</span><span>Escreva para contato@raizesdoamanha.org.br. Nossa equipe ter\xE1 prazer em ajudar.</span></div>
    <dialog class="feedback-modal" aria-labelledby="modal-titulo"><div class="modal-content"><button class="modal-close" type="button" aria-label="Fechar janela" data-close-modal>\xD7</button><span class="modal-icon" aria-hidden="true">\u2665</span><h2 id="modal-titulo">Que bom ter voc\xEA com a gente!</h2><p>Conte um pouco sobre voc\xEA no cadastro de voluntariado. Nossa equipe entrar\xE1 em contato para conversar sobre as formas de participa\xE7\xE3o.</p><a class="button button-primary" href="#/cadastro" data-route="cadastro">Fazer meu cadastro <span aria-hidden="true">\u2192</span></a></div></dialog>
    <section class="engagement-section container" aria-labelledby="voluntariado-titulo"><div class="section-heading"><div><span class="eyebrow">Participe de perto</span><h2 id="voluntariado-titulo">Voluntariado</h2></div><p>Doe seu tempo e suas habilidades para apoiar as atividades e fortalecer as comunidades atendidas.</p></div><div class="engagement-grid"><article class="engagement-card"><h3>Atividades educativas</h3><p>Colabore com leitura, refor\xE7o escolar e oficinas para crian\xE7as e jovens.</p><a href="#/cadastro" data-route="cadastro">Tenho interesse <span aria-hidden="true">\u2192</span></a></article><article class="engagement-card"><h3>A\xE7\xF5es com fam\xEDlias</h3><p>Ajude na organiza\xE7\xE3o de encontros, acolhimento e atividades comunit\xE1rias.</p><a href="#/cadastro" data-route="cadastro">Quero participar <span aria-hidden="true">\u2192</span></a></article><article class="engagement-card"><h3>Comunica\xE7\xE3o e eventos</h3><p>Compartilhe suas habilidades em comunica\xE7\xE3o, cria\xE7\xE3o e apoio a eventos.</p><a href="#/cadastro" data-route="cadastro">Conhe\xE7a o cadastro <span aria-hidden="true">\u2192</span></a></article></div></section>
    <section class="donation-section" aria-labelledby="doacoes-titulo"><div class="container donation-inner"><div><span class="eyebrow">Apoie nossas iniciativas</span><h2 id="doacoes-titulo">Doa\xE7\xF5es e campanhas</h2><p>As contribui\xE7\xF5es ajudam a manter as atividades educativas, apoiar fam\xEDlias e realizar a\xE7\xF5es nas comunidades.</p></div><div class="donation-list"><article><h3>Contribui\xE7\xE3o financeira</h3><p>Apoie os custos dos projetos e materiais utilizados nas atividades.</p></article><article><h3>Materiais para aprender</h3><p>Doe livros, cadernos e materiais escolares em bom estado para as a\xE7\xF5es educativas.</p></article><article><h3>Campanhas solid\xE1rias</h3><p>Participe das campanhas de arrecada\xE7\xE3o e ajude a divulgar as necessidades das comunidades.</p></article><a class="button button-primary" href="#/cadastro" data-route="cadastro">Quero saber como ajudar <span aria-hidden="true">\u2192</span></a></div></div></section>
    <section class="partners-band"><div class="container partners-inner"><div><span class="eyebrow eyebrow-light">Nossa forma de fazer</span><h2>Com a comunidade,<br><em>sempre.</em></h2></div><p>Nenhuma mudan\xE7a acontece sozinha. Constru\xEDmos cada a\xE7\xE3o junto de moradores, escolas, profissionais e parceiros locais \u2014 porque quem vive o desafio tamb\xE9m conhece a pot\xEAncia da solu\xE7\xE3o.</p></div></section>
    <section class="cta-strip container"><div><span class="eyebrow">Fa\xE7a parte</span><h2>Uma boa ideia cresce<br>quando \xE9 compartilhada.</h2></div><a class="button button-primary" href="#/cadastro" data-route="cadastro">Some ao nosso time <span aria-hidden="true">\u2192</span></a></section>`,cadastro:`<section class="join-hero"><div class="container join-hero-inner"><div><span class="eyebrow eyebrow-light"><span class="eyebrow-dot"></span> Tem espa\xE7o pra voc\xEA aqui</span><h1>O pr\xF3ximo cap\xEDtulo<br>come\xE7a <em>com voc\xEA.</em></h1><p>Seu tempo, sua experi\xEAncia e seu cuidado podem abrir novos caminhos. Conte um pouco sobre voc\xEA e vamos encontrar a melhor forma de caminhar juntos.</p></div><div class="join-mark" aria-hidden="true"><span>\u2733</span><small>cuidar<br>transforma</small></div></div></section>
    <section class="form-section container"><aside class="form-aside"><span class="eyebrow">Por que participar?</span><h2>Seu jeito de ajudar<br>faz a diferen\xE7a.</h2><p>Voc\xEA pode contribuir de muitas formas. A gente conversa para encontrar uma atividade que combine com seus interesses e disponibilidade.</p><ul class="benefit-list"><li><span aria-hidden="true">\u2733</span><span><strong>Impacto de verdade</strong><small>Sua presen\xE7a fortalece iniciativas locais.</small></span></li><li><span aria-hidden="true">\u2661</span><span><strong>Uma rede que acolhe</strong><small>Voc\xEA nunca caminha sozinho por aqui.</small></span></li><li><span aria-hidden="true">\u2197</span><span><strong>Aprendizado m\xFAtuo</strong><small>Todo mundo tem algo para compartilhar.</small></span></li></ul><div class="aside-note"><span aria-hidden="true">\u201C</span><p>Quando a gente se junta, o cuidado vira transforma\xE7\xE3o.</p></div></aside>
      <div class="form-card" id="formulario"><div class="form-card-head"><div><span class="eyebrow">Cadastro de interesse</span><h2>Vamos nos conhecer?</h2></div><span class="required-note"><span aria-hidden="true">*</span> Campo obrigat\xF3rio</span></div>
        <form id="volunteer-form" action="#formulario" method="get">
          <fieldset><legend>Dados pessoais</legend><div class="field-grid"><div class="field field-full"><label for="nome">Nome completo <span>*</span></label><input id="nome" name="nome" type="text" autocomplete="name" placeholder="Como podemos te chamar?" minlength="3" maxlength="100" required><small class="field-hint">Informe seu nome e sobrenome.</small></div>
          <div class="field"><label for="email">E-mail <span>*</span></label><input id="email" name="email" type="email" autocomplete="email" placeholder="voce@exemplo.com" maxlength="120" required></div>
          <div class="field"><label for="telefone">Celular com DDD <span>*</span></label><input id="telefone" name="telefone" type="tel" inputmode="numeric" autocomplete="tel" placeholder="(11) 99999-9999" maxlength="15" pattern="\\(\\d{2}\\) \\d{4,5}-\\d{4}" data-mask="phone" title="Digite um telefone v\xE1lido com DDD, por exemplo (11) 99999-9999" required><small class="field-hint">Ex.: (11) 99999-9999</small></div>
          <div class="field"><label for="nascimento">Data de nascimento <span>*</span></label><input id="nascimento" name="nascimento" type="date" autocomplete="bday" required></div>
          <div class="field"><label for="cpf">CPF <span>*</span></label><input id="cpf" name="cpf" type="text" inputmode="numeric" autocomplete="off" placeholder="000.000.000-00" maxlength="14" pattern="\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}" data-mask="cpf" title="Digite um CPF v\xE1lido no formato 000.000.000-00" required><small class="field-hint">Seus dados s\xE3o tratados com cuidado.</small></div></div></fieldset>
          <fieldset class="interest-fieldset"><legend>Endere\xE7o</legend><div class="field-grid"><div class="field field-full"><label for="endereco">Endere\xE7o <span>*</span></label><input id="endereco" name="endereco" type="text" autocomplete="address-line1" placeholder="Rua, avenida e n\xFAmero" minlength="5" maxlength="120" required></div>
          <div class="field"><label for="cep">CEP <span>*</span></label><input id="cep" name="cep" type="text" inputmode="numeric" autocomplete="postal-code" placeholder="00000-000" maxlength="9" pattern="\\d{5}-\\d{3}" data-mask="cep" title="Digite um CEP v\xE1lido no formato 00000-000" required></div>
          <div class="field"><label for="cidade">Cidade <span>*</span></label><input id="cidade" name="cidade" type="text" autocomplete="address-level2" placeholder="Sua cidade" minlength="2" maxlength="70" required></div>
          <div class="field"><label for="estado">Estado <span>*</span></label><select id="estado" name="estado" autocomplete="address-level1" required><option value="" selected disabled>Selecione</option><option value="AC">Acre</option><option value="AL">Alagoas</option><option value="AP">Amap\xE1</option><option value="AM">Amazonas</option><option value="BA">Bahia</option><option value="CE">Cear\xE1</option><option value="DF">Distrito Federal</option><option value="ES">Esp\xEDrito Santo</option><option value="GO">Goi\xE1s</option><option value="MA">Maranh\xE3o</option><option value="MT">Mato Grosso</option><option value="MS">Mato Grosso do Sul</option><option value="MG">Minas Gerais</option><option value="PA">Par\xE1</option><option value="PB">Para\xEDba</option><option value="PR">Paran\xE1</option><option value="PE">Pernambuco</option><option value="PI">Piau\xED</option><option value="RJ">Rio de Janeiro</option><option value="RN">Rio Grande do Norte</option><option value="RS">Rio Grande do Sul</option><option value="RO">Rond\xF4nia</option><option value="RR">Roraima</option><option value="SC">Santa Catarina</option><option value="SP">S\xE3o Paulo</option><option value="SE">Sergipe</option><option value="TO">Tocantins</option></select></div></div></fieldset>
          <fieldset class="interest-fieldset"><legend>Como quer participar?</legend><div class="field-grid"><div class="field"><label for="interesse">Tenho interesse em <span>*</span></label><select id="interesse" name="interesse" required><option value="" selected disabled>Escolha uma op\xE7\xE3o</option><option value="educacao">Educa\xE7\xE3o e atividades com crian\xE7as</option><option value="familias">Acolhimento de fam\xEDlias</option><option value="juventude">Mentoria de jovens</option><option value="comunicacao">Comunica\xE7\xE3o e cria\xE7\xE3o</option><option value="eventos">Eventos e a\xE7\xF5es</option><option value="outros">Outra forma de contribuir</option></select></div><div class="field"><label for="disponibilidade">Disponibilidade <span>*</span></label><select id="disponibilidade" name="disponibilidade" required><option value="" selected disabled>Escolha uma op\xE7\xE3o</option><option value="semana">Durante a semana</option><option value="noite">No per\xEDodo da noite</option><option value="fim-de-semana">Fins de semana</option><option value="flexivel">Flex\xEDvel</option></select></div><div class="field field-full"><label for="mensagem">Quer contar mais alguma coisa? <span class="optional">Opcional</span></label><textarea id="mensagem" name="mensagem" rows="3" maxlength="500" placeholder="Conte sobre suas experi\xEAncias, ideias ou d\xFAvidas..."></textarea><small class="field-hint">At\xE9 500 caracteres.</small></div></div></fieldset>
          <div class="consent-row"><input id="consentimento" name="consentimento" type="checkbox" required><label for="consentimento">Concordo com o uso dos meus dados para contato sobre oportunidades de voluntariado, conforme nossa <a href="#privacidade">pol\xEDtica de privacidade</a>. <span>*</span></label></div>
          <p class="form-notice" id="form-notice" role="status" aria-live="polite"></p><button class="button button-primary submit-button" type="submit">Enviar meu cadastro <span aria-hidden="true">\u2192</span></button><p class="form-footnote">Sem compromisso. Nossa equipe entrar\xE1 em contato para conversar.</p>
        </form>
      </div></section>`},window.SITE_COMPONENTS=(function(){const o=[{id:"quintal-saber",number:"01",category:"EDUCA\xC7\xC3O",image:"foto2.jpg",alt:"Crian\xE7as participam de uma atividade educativa",status:"Em andamento",tone:"success",kicker:"Aprender para florescer",title:"Quintal do Saber",description:"Refor\xE7o escolar, leitura e oficinas criativas em um espa\xE7o seguro onde a curiosidade \xE9 sempre bem-vinda.",metric:"180",metricLabel:"crian\xE7as por ano",location:"Zona Norte",imageClass:"project-image-one",cardClass:"project-card-feature"},{id:"rede-afeto",number:"02",category:"BEM-ESTAR",image:"foto3.jpg",alt:"Fam\xEDlia reunida em um momento de conviv\xEAncia",status:"Inscri\xE7\xF5es abertas",tone:"info",kicker:"Cuidar de quem cuida",title:"Rede de Afeto",description:"Acolhimento, rodas de conversa e orienta\xE7\xE3o para fam\xEDlias fortalecerem seus v\xEDnculos e redes de apoio.",metric:"95",metricLabel:"fam\xEDlias acompanhadas",location:"4 bairros",imageClass:"project-image-two",cardClass:""},{id:"primeiro-passo",number:"03",category:"JUVENTUDE",image:"foto4.jpg",alt:"Jovens reunidos em uma atividade em grupo",status:"Conclu\xEDdo",tone:"neutral",kicker:"Novos caminhos",title:"Primeiro Passo",description:"Mentoria, forma\xE7\xE3o e conex\xE3o com oportunidades de trabalho para jovens descobrirem seu potencial.",metric:"72",metricLabel:"jovens formados",location:"Desde 2022",imageClass:"project-image-three",cardClass:""}];function e(a){return String(a).replace(/[&<>"']/g,i=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[i])}function s(a){return`<article class="project-card ${e(a.cardClass)}">
      <div class="project-image ${e(a.imageClass)}"><picture><img src="imagens/${e(a.image)}" alt="${e(a.alt)}"></picture><span class="project-number">${e(a.number)} / ${e(a.category)}</span></div>
      <div class="project-body"><button class="favorite-toggle" type="button" data-favorite-id="${e(a.id)}" aria-pressed="false"><span aria-hidden="true">\u2661</span><span>Salvar projeto</span></button><span class="badge badge-${e(a.tone)}">${e(a.status)}</span><span class="card-kicker">${e(a.kicker)}</span><h3>${e(a.title)}</h3><p>${e(a.description)}</p>
        <div class="project-meta"><span><strong>${e(a.metric)}</strong> ${e(a.metricLabel)}</span><span class="meta-separator">\xB7</span><span>${e(a.location)}</span></div>
      </div>
    </article>`}return{renderProjects:()=>o.map(s).join("")}})();
